<script setup>
import { computed, reactive, ref, watch } from 'vue'
import tables from '../../../../standards/asce7-10-seismic-v1.json'
import { demoMode } from '../api'
import { seismicRequest, bridgeRequest, bridgeField } from '../seismic-api'
const sourceHref = `${import.meta.env.BASE_URL}standards/asce7-10.pdf#page=109`
const props = defineProps({ locale: { type: String, default: 'vi' } })
const text = (vi, en) => props.locale === 'vi' ? vi : en
const titles = computed(() => [text('Dự án & Địa điểm','Project & Site'),text('Phổ thiết kế','Design Spectrum'),text('Hệ kháng chấn','Seismic Systems'),text('Nguồn khối lượng SAP2000','SAP2000 Mass Source'),text('Lực cắt đáy / ELF','Base Shear / ELF'),text('Kiểm tra phổ phản ứng','Response Spectrum Verification'),text('Chuyển vị tầng & P-Delta','Story Drift & P-Delta'),text('Báo cáo & Xuất','Reports & Export'),text('QA & Kiểm tra thiết kế','QA & Design Review')])
const section = ref(0), busy = ref(false), error = ref(''), result = ref(null), stale = ref(false), runId = ref(null)
const input = reactive({ project: { name: '', region: '', units: 'SI', height: 11, Ss: .38, S1: .14, risk: 'II', TL: 8, TL_source: '', hazard_source: '', site_source: '', site_method: 'manual', site_class: 'E', profile_screened: false, rock_confirmed: false, site_f: false, soft_clay_e: false, site_specific: false, layers: [{top:0,bottom:30,value:20}] }, directions: {X:{system:'B2',moment_eligible:false},Y:{system:'B2',moment_eligible:false}}, mass: {source:'',basis:'model_mass',scope_confirmed:false,net_model_mass_confirmed:false,mass_source_association_confirmed:false,reaction_scope_confirmed:false,mass_row_id:'',pattern_rows:{}}, rs: {X:{case:'',row_id:'',case_type:'response_spectrum',global_axes:false,modal_combination_confirmed:false,applicability_confirmed:false,result_state:'raw',applied_multiplier:1,scale_source:''},Y:{case:'',row_id:'',case_type:'response_spectrum',global_axes:false,modal_combination_confirmed:false,applicability_confirmed:false,result_state:'raw',applied_multiplier:1,scale_source:''}} })
watch(input,()=>{ if(result.value)stale.value=true },{deep:true})
const imported = ref(null), preview = ref(null), mappings = ref([]), importId = ref(null), file = ref(null)
const selectedDefinition = computed(()=>imported.value?.definitions.find(d=>d.name===input.mass.source))
const reactionRows = computed(()=>imported.value?.reactions || [])
const rsLabel = key => ({signed_kN:text('Lực cắt có dấu (kN)','Signed shear (kN)'),absolute_kN:text('Lực cắt tuyệt đối hiện tại (kN)','Current absolute shear (kN)'),raw_kN:text('Lực cắt chưa scale bổ sung (kN)','Shear before additional scaling (kN)'),existing_multiplier:text('Hệ số bổ sung đã áp dụng','Existing additional multiplier'),threshold_kN:text('Ngưỡng 0.85 V_ELF (kN)','0.85 V_ELF threshold (kN)'),ratio:text('Tỷ số hiện tại / V_ELF','Current / V_ELF ratio'),required_total_multiplier:text('Tổng hệ số cần so với kết quả gốc','Total required multiplier from raw result'),additional_multiplier:text('Hệ số còn cần tăng thêm','Further multiplier required')})[key] || key
const fmt = v => v === null || v === undefined ? '—' : typeof v === 'number' ? v.toLocaleString('en-US',{maximumFractionDigits:6}) : v
const displayed = computed(()=>result.value?.directions || {})
const plot = computed(()=>{const c=result.value?.spectrum?.curve;if(!c?.length)return '';const maxX=Math.max(...c.map(p=>p.T)),maxY=Math.max(...c.map(p=>p.Sa));return c.map(p=>`${50+650*p.T/maxX},${230-200*p.Sa/maxY}`).join(' ')})
const axisWeight = computed(()=>input.project.units==='US'?4.4482216152605:1)
async function perform(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function calculate(){await perform(async()=>{const data=await seismicRequest('/calculate',{input,import_id:importId.value});result.value=data.result;runId.value=data.run_id;stale.value=false})}
function setPreview(data){preview.value=data;importId.value=data.import_id;imported.value=null;input.mass.source='';input.mass.mass_row_id='';input.mass.pattern_rows={};input.mass.scope_confirmed=false;for(const axis of ['X','Y']){input.rs[axis].row_id='';input.rs[axis].case='';}mappings.value=data.preview.sheets.map(s=>({...s,units:'',element_mass:'',additional_mass:'',from_loads:''}));stale.value=true}
async function upload(){await perform(async()=>{if(!file.value)throw new Error(text('Chọn tệp XLSX xuất từ SAP2000.','Choose an SAP2000 XLSX export.'));const form=new FormData();form.append('file',file.value);setPreview(await seismicRequest('/imports/preview',form))})}
async function confirm(){await perform(async()=>{const cleaned=mappings.value.map(m=>{const r={name:m.name,role:m.role,header_row:Number(m.header_row),units:m.units,units_row:m.units_row,columns:Object.fromEntries(Object.entries(m.columns).filter(([,v])=>v!==''&&v!==null).map(([k,v])=>[k,Number(v)]))};for(const flag of ['element_mass','additional_mass','from_loads'])if(m[flag]!=='')r[flag]=m[flag]==='true';return r});const data=await seismicRequest(`/imports/${importId.value}/confirm`,{mappings:cleaned});imported.value=data.dto;input.mass.source=data.dto.definitions[0]?.name || '';preview.value=null})}
const bridge = reactive({url:'http://127.0.0.1:8010',token:'',model:null,keys:[],selected:[],status:''})
watch(()=>[bridge.url,bridge.token],()=>{bridge.model=null;bridge.keys=[];bridge.selected=[];bridge.status=''})
async function connect(){await perform(async()=>{bridge.model=null;bridge.keys=[];bridge.selected=[];bridge.status='';const model=await bridgeRequest(bridge.url,bridge.token,'/model');if(!model.model)throw new Error('SAP model unavailable');const inventory=await bridgeRequest(bridge.url,bridge.token,'/tables');const keys=bridgeField(inventory,'TableKey');if(!Array.isArray(keys))throw new Error(inventory.reason || 'SAP database table API unavailable');bridge.model=model;bridge.keys=keys;bridge.status=text('Đã đọc mô hình và danh sách bảng','Model and table inventory read')})}
async function readBridge(){await perform(async()=>{if(!bridge.model||!bridge.selected.length)throw new Error('Connect and select tables first');const data=[];for(const table_key of bridge.selected)data.push(await bridgeRequest(bridge.url,bridge.token,'/table',{expected_model:bridge.model.model,table_key,max_records:20000}));setPreview(await seismicRequest('/imports/preview',{tables:data}));bridge.status=text('Đã đọc bảng; cần xem trước và xác nhận','Tables read; preview and confirmation required')})}
function selectRs(axis){const selection=input.rs[axis],row=reactionRows.value.find(r=>r.id===selection.row_id);selection.case=row?.case || ''}
function addLayer(){const last=input.project.layers.at(-1);input.project.layers.push({top:last?.bottom||0,bottom:30,value:20})}
</script>

<template>
<section class="seismic-workspace" data-testid="seismic-workspace">
  <header class="seismic-banner"><div><span>ASCE 7-10 · Chapters 11, 12, 20</span><h2>{{ text('Phân tích tải trọng động đất','Seismic load analysis') }}</h2><p>{{ text('Nguồn dữ liệu SAP2000 → Trọng lượng W → ELF → Kiểm tra phổ phản ứng','SAP2000 source → Seismic weight W → ELF → Response spectrum verification') }}</p></div><span class="edition">01–06</span></header>
  <p v-if="demoMode" class="notice">{{ text('Bản GitHub Pages chỉ hiển thị giao diện. Tính toán và nhập dữ liệu riêng tư cần mở ứng dụng Laravel GeekCalculus; không có kết nối SAP2000 tự động.','GitHub Pages displays the workspace. Calculations and private imports require the GeekCalculus Laravel application; SAP2000 is not automatically connected.') }}</p>
  <nav class="seismic-tabs" :aria-label="text('Các bước tính động đất','Seismic workflow')"><button v-for="(title,i) in titles" :key="i" type="button" :aria-current="section===i?'step':undefined" @click="section=i"><span>{{ String(i+1).padStart(2,'0') }}</span>{{ title }}<small v-if="i>5">Coming Soon</small></button></nav>
  <div class="seismic-toolbar"><span>{{ tables.version }} · {{ text('Kết quả cần kỹ sư kiểm tra','Engineering review required') }}</span><button v-if="section<6" type="button" :disabled="busy || demoMode" @click="calculate">{{ busy?text('Đang xử lý…','Working…'):text('Tính toán 01–06','Calculate 01–06') }}</button></div>
  <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="stale && result" role="status" class="notice">{{ text('Đầu vào đã thay đổi. Cần tính lại; kết quả bên dưới thuộc lần tính trước.','Inputs changed. Recalculate; results below belong to the previous snapshot.') }}</p>
  <section v-if="section===0" class="seismic-card">
    <h3>01 · {{ titles[0] }}</h3><div class="seismic-grid">
      <label>{{ text('Tên dự án','Project name') }}<input v-model="input.project.name"></label><label>{{ text('Khu vực','Region') }}<input v-model="input.project.region"></label>
      <label>{{ text('Hệ đơn vị chiều cao','Height unit system') }}<select v-model="input.project.units"><option>SI</option><option>US</option></select><small>{{ text('Đổi hệ đơn vị: nhập lại chiều cao; lớp địa chất luôn dùng m và m/s.','When switching units, re-enter height; soil layers always use m and m/s.') }}</small></label>
      <label>hₙ ({{ input.project.units==='US'?'ft':'m' }})<input v-model.number="input.project.height" type="number" min="0" step="any"></label>
      <label>Risk Category<select v-model="input.project.risk"><option v-for="r in ['I','II','III','IV']" :key="r">{{ r }}</option></select><small>Ie: I/II = 1; III = 1.25; IV = 1.5 · Table 1.5-2</small></label>
      <label>Ss (g)<input v-model.number="input.project.Ss" type="number" min="0" step="any"></label><label>S1 (g)<input v-model.number="input.project.S1" type="number" min="0" step="any"></label>
      <label>{{ text('Nguồn Ss/S1 (bản đồ, báo cáo, ngày)','Ss/S1 source (map, report, date)') }}<input v-model="input.project.hazard_source" required></label>
      <label>TL (s)<input v-model.number="input.project.TL" type="number" min="0" step="any"></label><label>{{ text('Nguồn TL','TL source') }}<input v-model="input.project.TL_source" required></label>
      <label>{{ text('Phương pháp phân loại đất','Site classification method') }}<select v-model="input.project.site_method"><option value="manual">{{ text('Nhập theo báo cáo địa chất','Manual, geotechnical report') }}</option><option value="N">N · 30m</option><option value="Vs">Vs · 30m</option></select></label>
      <label v-if="input.project.site_method==='manual'">Site Class<select v-model="input.project.site_class"><option v-for="c in ['A','B','C','D','E','F']" :key="c">{{ c }}</option></select></label>
      <label>{{ text('Nguồn địa chất / xác nhận phân loại','Geotechnical source / classification confirmation') }}<input v-model="input.project.site_source" required></label>
    </div>
    <div class="checks"><label><input v-model="input.project.site_f" type="checkbox">{{ text('Có tiêu chí đất loại F (§20.3.1)','Site F criteria present (§20.3.1)') }}</label><label><input v-model="input.project.soft_clay_e" type="checkbox">{{ text('Đất sét mềm thỏa §20.3.2 → E','Soft clay meeting §20.3.2 → E') }}</label><label><input v-model="input.project.site_specific" type="checkbox">{{ text('Cần nghiên cứu riêng / cách chấn / hệ giảm chấn','Site-specific study / isolation / damping system') }}</label></div>
    <div v-if="input.project.site_method!=='manual'">
      <p>{{ text('Hồ sơ liên tục đủ 30m; không tự suy đoán phần thiếu. N đo hiện trường ASTM D1586, giới hạn 100; không dùng N60 đã hiệu chỉnh.','Continuous complete 30m profile; missing strata are never guessed. Field ASTM D1586 N is capped at 100; do not substitute corrected N60.') }}</p>
      <div class="table-scroll"><table><thead><tr><th>Top (m)</th><th>Bottom (m)</th><th>{{ input.project.site_method==='N'?'N (blows/ft)':'Vs (m/s)' }}</th><th></th></tr></thead><tbody><tr v-for="(l,i) in input.project.layers" :key="i"><td><input v-model.number="l.top" :aria-label="`Layer ${i+1} top`" type="number" step="any"></td><td><input v-model.number="l.bottom" :aria-label="`Layer ${i+1} bottom`" type="number" step="any"></td><td><input v-model.number="l.value" :aria-label="`Layer ${i+1} value`" type="number" step="any"></td><td><button @click="input.project.layers.splice(i,1)">×</button></td></tr></tbody></table></div>
      <button @click="addLayer">{{ text('Thêm lớp','Add layer') }}</button><div class="checks"><label><input v-model="input.project.profile_screened" type="checkbox">{{ text('Đã kiểm tra tiêu chí F và sét mềm E theo báo cáo','F and soft-clay E criteria screened against report') }}</label><label><input v-model="input.project.rock_confirmed" type="checkbox">{{ text('Đá A/B: đã kiểm tra lớp phủ, tính liên tục và xác nhận địa chất','Rock A/B: cover, continuity and geotechnical confirmation checked') }}</label></div>
    </div>
    <p v-if="result">Site Class: <strong>{{ result.site.class }}</strong> · {{ result.site.reference }} · {{ fmt(result.site.average) }}</p>
  </section>
  <section v-else-if="section===1" class="seismic-card">
    <h3>02 · {{ titles[1] }}</h3><p>SMS = Fa·Ss; SM1 = Fv·S1; SDS = ⅔SMS; SD1 = ⅔SM1; T0 = 0.2SD1/SDS; Ts = SD1/SDS.</p>
    <p>{{ text('Nội suy tuyến tính theo bảng 11.4-1/2 của bản 2010. Đất F và yêu cầu nghiên cứu riêng không dùng phổ tổng quát.','Linear interpolation of the 2010 Tables 11.4-1/2. Site F and site-specific requirements disable the generic spectrum.') }}</p>
    <template v-if="result?.spectrum.status==='calculated'"><div class="seismic-metrics"><div v-for="key in ['Fa','Fv','SMS','SM1','SDS','SD1','T0','Ts','TL','Ie','SDC']" :key="key"><small>{{ key }}</small><strong>{{ fmt(result.spectrum[key]) }}</strong></div></div>
    <svg class="spectrum-chart" viewBox="0 0 740 280" role="img" :aria-label="text('Phổ thiết kế Sa theo chu kỳ T','Design spectrum Sa versus period T')"><path d="M50 20V230H710" fill="none" stroke="currentColor"/><polyline :points="plot" fill="none" stroke="#126e91" stroke-width="3"/><text x="10" y="18">Sa (g)</text><text x="640" y="265">T (s)</text><text x="50" y="250">0</text><text x="660" y="248">{{ fmt(Math.max(4,1.2*result.spectrum.TL)) }}</text><text x="58" y="32">SDS = {{ fmt(result.spectrum.SDS) }}g</text></svg>
    <p>{{ result.spectrum.reference }}</p></template><p v-else class="notice">{{ result?.spectrum.reason || text('Nhập nguồn dữ liệu và bấm Tính toán để dựng phổ.','Enter source data and calculate to draw the spectrum.') }}</p>
    <details><summary>{{ text('Hệ số theo tài liệu dự án / kiểm tra workbook','Documented coefficient overrides / workbook check') }}</summary><p>{{ text('Ví dụ lịch sử Fa=2.08 là làm tròn của nội suy 2.084. Nhập khác bảng cần nguồn và lý do; luôn yêu cầu kiểm tra.', 'Historical Fa=2.08 rounds the interpolated 2.084. Overrides require a source and reason and remain subject to review.') }}</p><div class="seismic-grid"><label v-for="key in ['Fa_override','Fv_override','Ie_override']" :key="key">{{ key }}<input v-model.number="input.project[key]" type="number" min="0" step="any" @change="input.project[key] === '' && delete input.project[key]"></label><label>{{ text('Nguồn hệ số thay thế','Override source') }}<input v-model="input.project.coefficient_source"></label><label>{{ text('Lý do thay hệ số','Coefficient override reason') }}<input v-model="input.project.coefficient_reason"></label><label>{{ text('Lý do thay Ie','Ie override reason') }}<input v-model="input.project.Ie_reason"></label></div><p v-if="result?.spectrum.override_review_required" class="notice">Override · REVIEW_REQUIRED · table Fa={{ fmt(result.spectrum.table_Fa) }} / Fv={{ fmt(result.spectrum.table_Fv) }}</p></details>
    <details><summary>{{ text('Bảng hệ số và nguồn','Coefficient tables and source') }}</summary><p>{{ tables.source.sha256 }}</p><div v-for="name in ['Fa','Fv']" :key="name" class="table-scroll"><table><caption>{{ tables[name].reference }} · PDF 109 / printed 66</caption><thead><tr><th>Site</th><th v-for="x in tables[name].x" :key="x">{{ x }}</th></tr></thead><tbody><tr v-for="c in ['A','B','C','D','E']" :key="c"><th>{{ c }}</th><td v-for="(v,i) in tables[name][c]" :key="i">{{ v }}</td></tr></tbody></table></div></details>
  </section>
  <section v-else-if="section===2" class="seismic-card">
    <h3>03 · {{ titles[2] }}</h3><p>Ta = Ct·hₙ(ft)ˣ; Tcap = Cu·Ta; Tused = min(Tmodal, Tcap). {{ text('Nếu không có Tmodal, dùng Ta.','Without Tmodal, Ta is used.') }}</p>
    <div class="seismic-grid axes"><article v-for="axis in ['X','Y']" :key="axis"><h4>U{{ axis }}</h4><label>SFRS<select v-model="input.directions[axis].system"><option v-for="sys in tables.systems" :key="sys.id" :value="sys.id">{{ sys.id }} · {{ props.locale==='vi'?sys.vi:sys.name }}</option></select></label>
    <label>Tmodal (s) · {{ text('tùy chọn','optional') }}<input v-model.number="input.directions[axis].Tmodal" type="number" min="0" step="any" @change="input.directions[axis].Tmodal === '' && delete input.directions[axis].Tmodal"></label>
    <label class="check"><input v-model="input.directions[axis].moment_eligible" type="checkbox">{{ text('Khung mô men chịu 100% lực, không bị cấu kiện cứng cản trở (§12.8.2)','Moment frame resists 100%, no adjoining rigid restraint (§12.8.2)') }}</label>
    <template v-if="displayed[axis]"><p class="notice" v-if="displayed[axis].system.reason">{{ displayed[axis].system.reason }}</p><dl><template v-for="key in ['R','Cd','Omega0','Ct','x','Cu','Ta','Tcap','Tmodal','Tused']" :key="key"><dt>{{ key }}</dt><dd>{{ fmt(displayed[axis].system[key]) }}</dd></template></dl><p>{{ displayed[axis].system.reference }}</p></template></article></div>
    <p class="notice">{{ text('Chỉ các hàng đã đối chiếu được phép chọn. Điều kiện chi tiết cấu tạo, hệ hỗn hợp, điều kiện phương pháp ELF và các ngoại lệ chiều cao cần kỹ sư xét riêng. Không tự áp dụng ngoại lệ.','Only transcribed rows are selectable. Detailing, mixed systems, ELF eligibility and height exceptions require engineering review. Exceptions are never automatically applied.') }}</p>
  </section>
  <section v-else-if="section===3" class="seismic-card">
    <h3>04 · {{ titles[3] }}</h3><p>{{ text('Chỉ nhận dữ liệu SAP2000: định nghĩa Mass Source không tự tạo W. Xem trước và xác nhận ánh xạ trước khi sử dụng.','SAP2000 sources only: a Mass Source definition does not establish W. Preview and confirm mapping before use.') }}</p>
    <div class="import-options"><article><h4>Excel · .xlsx</h4><label>{{ text('Tệp xuất bảng SAP2000','SAP2000 table export') }}<input type="file" accept=".xlsx" @change="file=$event.target.files[0]"></label><button :disabled="busy||demoMode" @click="upload">{{ text('Tải lên & Xem trước','Upload & Preview') }}</button><p>Mass Source Definitions, Mass Summary, Base Reactions, Load Case Definitions / Loads Applied.</p></article>
    <article><h4>SAP2000 API · V2</h4><label>Connector URL<input v-model="bridge.url"></label><label>{{ text('Token connector (chỉ bộ nhớ phiên)','Connector token (page memory only)') }}<input v-model="bridge.token" type="password" autocomplete="off"></label><button :disabled="busy||demoMode" @click="connect">{{ text('Kết nối & Đọc danh sách bảng','Connect & Read table inventory') }}</button><p role="status">{{ bridge.status || text('Chưa kết nối. Cần Windows + SAP2000 + connector V2 đang chạy.','Not connected. Requires Windows, SAP2000 and a running V2 connector.') }}</p>
    <template v-if="bridge.model"><p>{{ bridge.model.model }}</p><label>{{ text('Chọn các bảng cần đọc','Select tables to read') }}<select v-model="bridge.selected" multiple size="5"><option v-for="key in bridge.keys" :key="key">{{ key }}</option></select></label><button :disabled="busy" @click="readBridge">{{ text('Đọc bảng & Xem trước','Read tables & Preview') }}</button></template></article></div>
    <div v-if="preview" class="import-preview"><h4>{{ text('Xem trước & Ánh xạ cột','Preview & Column mapping') }}</h4><p>{{ preview.provenance.filename || preview.provenance.model }}</p>
      <article v-for="m in mappings" :key="m.name"><h5>{{ m.name }} · {{ m.row_count }} rows</h5><div class="seismic-grid"><label>Role<select v-model="m.role"><option v-for="r in preview.preview.roles" :key="r">{{ r }}</option></select></label><label>Header row<input v-model.number="m.header_row" type="number" min="1"></label><label>Units<select v-model="m.units"><option value="">{{ text('Chọn đúng đơn vị nguồn','Choose original units') }}</option><option v-for="u in ['kg','tonne','kN-s2/m','kip-s2/ft','lbm','kN','N','kip','lbf','kgf','tf']" :key="u">{{ u }}</option></select></label></div>
      <p v-if="m.units_row">Units metadata · row {{ m.units_row }}: {{ m.units_metadata.join(', ') }}</p><template v-if="m.role!=='ignore'"><div class="mapping-grid"><label v-for="key in preview.preview.fields" :key="key">{{ key }}<select v-model="m.columns[key]"><option value="">—</option><option v-for="(_,i) in Array.from({length:Math.max(1,...m.sample.map(r=>r.cells.length))})" :key="i" :value="i">{{ i+1 }} · {{ m.sample.find(r=>r.row===Number(m.header_row))?.cells[i] || '' }}</option></select></label></div>
      <div v-if="m.role==='definition'" class="seismic-grid"><label v-for="flag in ['element_mass','additional_mass','from_loads']" :key="flag">{{ flag }}<select v-model="m[flag]"><option value="">{{ text('Đọc từ cột đã ánh xạ','Read mapped column') }}</option><option value="true">Yes</option><option value="false">No</option></select></label></div>
      <div class="table-scroll"><table><tbody><tr v-for="r in m.sample" :key="r.row"><th>{{ r.row }}</th><td v-for="(c,i) in r.cells" :key="i">{{ c }}</td></tr></tbody></table></div><p v-if="m.merged_cells.length">Merged cells: {{ m.merged_cells.join(', ') }}</p></template></article>
      <button :disabled="busy" @click="confirm">{{ text('Xác nhận ánh xạ & Nhập','Confirm mapping & Import') }}</button>
    </div>
    <template v-if="imported"><p class="success">{{ text('Đã nhập, lưu nguồn và đơn vị gốc','Imported with source and original-unit lineage') }} · {{ imported.definitions.length }} Mass Sources · {{ imported.reactions.length }} reactions</p>
    <label>Mass Source<select v-model="input.mass.source"><option value="">—</option><option v-for="d in imported.definitions" :key="d.name">{{ d.name }}</option></select></label>
    <template v-if="selectedDefinition"><pre>{{ selectedDefinition.flags }}</pre><div class="table-scroll"><table><thead><tr><th>Load pattern</th><th>Multiplier</th></tr></thead><tbody><tr v-for="(v,k) in selectedDefinition.patterns" :key="k"><td>{{ k }}</td><td>{{ v }}</td></tr></tbody></table></div></template>
    <label>{{ text('Cơ sở xác định W','Weight derivation basis') }}<select v-model="input.mass.basis"><option value="model_mass">{{ text('Tổng khối lượng ròng từ SAP2000','SAP2000 net model mass') }}</option><option value="pattern_reactions">{{ text('Phản lực từng pattern đã xác nhận (chỉ nguồn từ tải)','Verified individual-pattern reactions (load-only source)') }}</option></select></label>
    <div v-if="input.mass.basis==='model_mass'"><label>{{ text('Dòng tổng khối lượng mô hình','Total model mass row') }}<select v-model="input.mass.mass_row_id"><option value="">—</option><option v-for="m in imported.masses" :key="m.id" :value="m.id">{{ m.id }} · {{ m.source }} · UX={{ fmt(m.mass_x_kg) }}kg / UY={{ fmt(m.mass_y_kg) }}kg</option></select></label><label class="check"><input v-model="input.mass.mass_source_association_confirmed" type="checkbox">{{ text('Nếu bảng không có tên nguồn: đã xác nhận dòng khối lượng dùng đúng Mass Source đang chọn.','If the table omits a source name: confirmed this mass row uses the selected Mass Source.') }}</label><label class="check"><input v-model="input.mass.net_model_mass_confirmed" type="checkbox">{{ text('Đã xác nhận tổng ròng, nguồn Mass Source, ràng buộc, không cộng trùng khối lượng phần tử/phụ/từ tải.','Confirmed net total, Mass Source association, constraints, no duplicated element/additional/load mass.') }}</label></div>
    <div v-else><label v-for="(v,pattern) in selectedDefinition?.patterns || {}" :key="pattern">{{ pattern }} × {{ v }}<select v-model="input.mass.pattern_rows[pattern]"><option value="">—</option><option v-for="r in reactionRows" :key="r.id" :value="r.id">{{ r.case }} · {{ r.step }} {{ r.step_number }} · FZ={{ fmt(r.FZ_kN) }}kN · {{ r.id }}</option></select></label><label class="check"><input v-model="input.mass.reaction_scope_confirmed" type="checkbox">{{ text('Mỗi dòng là tổng phản lực toàn mô hình +Z, trường hợp tĩnh tuyến tính một pattern hệ số 1; tự trọng đúng một lần, không tổ hợp/envelope; đã kiểm tra ràng buộc.','Each row is complete global +Z model reaction from one linear-static pattern at factor 1; self weight once, no combinations/envelopes; constraints checked.') }}</label></div>
    <label class="check"><input v-model="input.mass.scope_confirmed" type="checkbox">{{ text('Đã kiểm tra phạm vi khối lượng hữu hiệu theo §12.7.2: tự trọng, thiết bị cố định, vách ngăn, hoạt tải kho, tuyết khi áp dụng.','Effective mass scope reviewed under §12.7.2: self weight, permanent equipment, partitions, storage live load and snow where applicable.') }}</label></template>
    <div v-if="result?.mass" class="mass-result"><h4>W = {{ fmt(result.mass.W_kN) }} kN · {{ result.mass.status }}</h4><pre>{{ result.mass.audit }}</pre><p>{{ text('Trường hợp không dùng để xác định W','Cases excluded from W') }}: {{ result.mass.excluded_cases.join(', ') }}</p></div>
  </section>
  <section v-else-if="section===4" class="seismic-card">
    <h3>05 · {{ titles[4] }}</h3><p>V = Cs·W · §12.8.1.1</p><p v-if="!result?.mass?.W_kN" class="notice">{{ text('Chưa có W được xác nhận từ SAP2000. Không tính V và không thay bằng giá trị mẫu.','Verified SAP2000 W is missing. V is disabled; no sample weight is substituted.') }}</p>
    <div class="table-scroll"><table><thead><tr><th>Axis</th><th>Cs basic</th><th>Cs upper</th><th>Cs minimum</th><th>Cs</th><th>W ({{ input.project.units==='US'?'kip':'kN' }})</th><th>V ({{ input.project.units==='US'?'kip':'kN' }})</th></tr></thead><tbody><tr v-for="axis in ['X','Y']" :key="axis"><th>{{ axis }}</th><td v-for="key in ['basic','upper','minimum','Cs']" :key="key">{{ fmt(displayed[axis]?.elf?.[key]) }}</td><td>{{ fmt(result?.mass?.W_kN==null?null:result.mass.W_kN/axisWeight) }}</td><td>{{ fmt(displayed[axis]?.elf?.V_kN==null?null:displayed[axis].elf.V_kN/axisWeight) }}</td></tr></tbody></table></div>
    <ul><li>Cs = SDS/(R/Ie) · Eq 12.8-2.</li><li>Upper: SD1/[T(R/Ie)] (T ≤ TL); SD1·TL/[T²(R/Ie)] (T &gt; TL) · Eqs 12.8-3/4.</li><li>Minimum: max(0.044·SDS·Ie, 0.01); S1 ≥ 0.6g: additionally 0.5·S1/(R/Ie) · Eqs 12.8-5/6.</li></ul><p class="notice">{{ text('Không tự áp dụng giảm SSI hoặc giới hạn Ss tùy chọn. Điều kiện dùng ELF và tính bất quy tắc cần kiểm tra theo §12.6.','No automatic SSI reduction or optional Ss cap. ELF eligibility and structural irregularity must be checked under §12.6.') }}</p>
  </section>
  <section v-else-if="section===5" class="seismic-card">
    <h3>06 · {{ titles[5] }}</h3><p>{{ text('Chọn chính xác một case phổ phản ứng và dòng kết quả đã tổ hợp mode cho từng trục toàn cục. Không chọn tổ hợp tải hay một mode đơn.','Select an individual response-spectrum case and a combined-modal result row for each global axis. Do not select a load combination or single mode.') }}</p><p v-if="!imported" class="notice">{{ text('Nhập Base Reactions từ Excel/API tại bước 04 trước.','Import Base Reactions through Excel/API in section 04 first.') }}</p>
    <p>{{ text('Cần nhập bảng định nghĩa load case để xác nhận loại Response Spectrum.','Import load-case definitions to verify the Response Spectrum case type.') }}</p><div class="seismic-grid axes"><article v-for="axis in ['X','Y']" :key="axis"><h4>Global F{{ axis }}</h4><label>Case / Step / Row<select v-model="input.rs[axis].row_id" @change="selectRs(axis)"><option value="">—</option><option v-for="r in reactionRows" :key="r.id" :value="r.id">{{ r.case }} · {{ r.step }} {{ r.step_number }} · F{{ axis }}={{ fmt(r[axis==='X'?'FX_kN':'FY_kN']) }}kN · {{ r.id }}</option></select></label>
    <label>{{ text('Trạng thái kết quả','Result state') }}<select v-model="input.rs[axis].result_state"><option value="raw">{{ text('Chưa áp dụng hệ số bổ sung 85%','Raw: no additional 85% scaling') }}</option><option value="scaled">{{ text('Đã áp dụng hệ số bổ sung','Already scaled by an additional multiplier') }}</option></select></label><label v-if="input.rs[axis].result_state==='scaled'">{{ text('Hệ số bổ sung đã áp dụng','Existing additional multiplier') }}<input v-model.number="input.rs[axis].applied_multiplier" type="number" min="0" step="any"></label><label>{{ text('Nguồn hệ số, đơn vị phổ và trường hợp phân tích','Scale provenance, spectrum units and analysis case') }}<input v-model="input.rs[axis].scale_source"></label>
    <label class="check"><input v-model="input.rs[axis].global_axes" type="checkbox">Global FX/FY {{ text('đã xác nhận','confirmed') }}</label><label class="check"><input v-model="input.rs[axis].modal_combination_confirmed" type="checkbox">{{ text('Case phổ phản ứng riêng, đã tổ hợp mode SRSS/CQC; không phải combo hoặc mode đơn','Individual RS case, combined SRSS/CQC modes; not a combo or single mode') }}</label><label class="check"><input v-model="input.rs[axis].applicability_confirmed" type="checkbox">{{ text('Đã xác nhận áp dụng §12.9.4.1, điều kiện mô hình và phạm vi phân tích','§12.9.4.1 applicability, model and analysis scope confirmed') }}</label>
    <template v-if="displayed[axis]?.rs"><h4 :class="displayed[axis].rs.status==='PASS'?'success':'notice'">{{ displayed[axis].rs.status }}</h4><dl><template v-for="key in ['signed_kN','absolute_kN','raw_kN','existing_multiplier','threshold_kN','ratio','required_total_multiplier','additional_multiplier']" :key="key"><dt>{{ rsLabel(key) }}</dt><dd>{{ fmt(displayed[axis].rs[key]) }}</dd></template></dl><p>{{ displayed[axis].rs.reference }}</p></template></article></div>
    <p class="notice">{{ text('Hệ số bổ sung khác với hệ số g/đơn vị phổ trong SAP2000. Chỉ hoàn nguyên hệ số đã ghi nhận; kết quả đã scale chỉ đề xuất phần cần tăng thêm. PASS chỉ là kiểm tra lực, không phải duyệt thiết kế; chuyển vị có quy tắc riêng §12.9.4.2.','Additional scaling differs from the SAP spectrum g/unit factor. Only documented additional multipliers are reversed; scaled results recommend only any further increase. PASS checks forces only, not design approval; drift uses §12.9.4.2.') }}</p>
  </section>
  <section v-else class="seismic-card coming-soon"><h3>{{ String(section+1).padStart(2,'0') }} · {{ titles[section] }}</h3><strong>Coming Soon</strong><p>{{ text('Chức năng này chưa triển khai trong giai đoạn 01–06.','This section is outside the implemented 01–06 phase.') }}</p></section>
  <footer><p>{{ text('Bản ghi tính toán','Calculation snapshot') }}: {{ runId || '—' }} · {{ text('Nguồn hệ số và đầu vào được lưu theo lần tính; không xác nhận toàn bộ công trình.','Coefficient version and inputs are saved per run; no whole-building approval is implied.') }}</p><a :href="sourceHref" target="_blank" rel="noopener">ASCE 7-10 · {{ text('Mở tài liệu nguồn','Open source') }}</a></footer>
</section>
</template>

